import socket
from concurrent.futures import ThreadPoolExecutor, as_completed

def resolve_host(host):
    try:
        return socket.gethostbyname(host)
    except socket.gaierror:
        return None

def check_port(host, port, timeout):
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.settimeout(timeout)
    code = s.connect_ex((host, port))
    s.close()
    return (port, code == 0)

def grab_banner(host, port, timeout=2):
    s = socket.socket()
    s.settimeout(timeout)
    try:
        s.connect((host, port))
        if port == 80 or port == 8080:
            s.sendall(b'HEAD / HTTP/1.0\r\n\r\n')
        banner = s.recv(1024).decode(errors='ignore').strip()
        return banner
    except:
        return None
    finally:
        s.close()

def scan_ports(target, start, end, timeout=0.5, threads=100):
    ip = resolve_host(target)
    if not ip:
        print(f"Could not resolve {target}")
        return []
    open_ports = []
    with ThreadPoolExecutor(max_workers=threads) as ex:
        futures = {ex.submit(check_port, ip, p, timeout): p for p in range(start, end+1)}
        for future in as_completed(futures):
            port, is_open = future.result()
            if is_open:
                service = socket.getservbyport(port, 'tcp') if port <= 1024 else 'unknown'
                banner = grab_banner(ip, port, timeout)
                open_ports.append({'port': port, 'service': service, 'banner': banner})
    return sorted(open_ports, key=lambda x: x['port'])

# Test
if __name__ == '__main__':
    results = scan_ports('127.0.0.1', 8000, 8005)
    for r in results:
        print(r)
